from summary_lib import *

def add(chap, sub):
    chap("App", "Appendices 1–4: Codes of Conduct & Resources", "in Ch 4/6", 3)
    sub("Appendix 1 — Fourth Schedule: Code of Conduct for AMC & trustees", 4,
      T(["#","Rule"],
        [["1","High standards of integrity and fairness"],
         ["2","Schemes not run or portfolios selected in the interest of sponsors, AMC/trustee directors or their associates"],
         ["3","Equitable, fair treatment of all classes of unitholders — favouring one set over another is not fair"],
         ["4","Adequate, accurate, explicit, timely information in simple language to all unitholders"],
         ["5","Avoid excessive concentration of business with broking firms/associates and excessive holding of units by few investors; avoid conflicts of interest — unitholders' interest paramount"],
         ["6","Assets, liabilities, bank and securities accounts of each scheme segregated and <b>ring-fenced</b>"],
         ["7","Invest per stated objectives, solely in unitholders' interest"],
         ["8","No unethical means to sell or induce"],
         ["9","High service standards, due diligence, proper care, independent professional judgment"],
         ["10","AMC: no exaggerated statements about qualifications, capability, achievements"],
         ["11","Sponsor/trustees/AMC/employees giving advice on a security in public media must disclose their interest incl. long/short positions; employees also disclose dependent family members' and employer's interest"]]) +
      K("Regulated entities and agents (MFDs, PMS distributors) must show registered name and registration number on social-media home page and at the start of each securities-market video/content"))
    sub("Appendix 2 — AMFI Code of Ethics (ACE)", 4,
      T(["Section","Key rules"],
        [["1 Integrity","High integrity &amp; fairness; schemes run for all unitholder classes — NOT for sponsors, member directors, trustees, brokers/intermediaries, associates, or a special class of unitholders"],
         ["2 Due diligence","High service, due diligence, independent judgment; adequate resources &amp; procedures"],
         ["3 Disclosures","Timely, simple info; annual disclosure of investment pattern, portfolio, expense ratios, portfolio turnover; trades with associates or significant unitholders → report to trustees with fairness justification + brief disclosure in annual/half-yearly reports; key investment personnel's own trades → compliance officer at least half-yearly, to trustees if conflict"],
         ["4 Professional selling","No unethical inducement, no exaggerated performance claims; true info; disclose risks before investment; documents on request; fair allotment and timely refunds; handle complaints fairly. Communications: don't present a scheme as a new share issue; no unrealistic expectations; no guaranteed returns except as in SID (with resources to meet them); state market risk clearly; no extraneous benefits; no misrepresentation"],
         ["5 Investment practices","Manage per fundamental objectives; don't knowingly trade securities with member's or trustee company's directors, officers, employees, or trustees"],
         ["6 Operations","Avoid conflicts; no <b>front running</b> (trading ahead of fund with non-public info); no <b>self-dealing</b>; nothing fraudulent/manipulative; no false market, price rigging, passing price-sensitive info; employees can't act as agents/brokers for member's schemes; no fundamental attribute change without unitholder approval (except due to regulation); avoid broker concentration and concentrated unitholding"],
         ["7 Reporting","Standardised valuation per SEBI; uniform performance reporting on <b>total return</b> basis; scheme-wise segregation of cash &amp; securities accounts"],
         ["8 Unfair competition","Nothing harmful to other members"],
         ["9 Statutes","Follow letter and spirit of laws"],
         ["10 Enforcement","Disseminate code; observance a condition of employment; violation = ground for revocation and discipline; employees sign receipt; internal controls; one compliance person with power to investigate; half-yearly &amp; annual reports to trustees; keep records ≥ <b>3 years</b>; adequate resources"]]) +
      KV([("Significant unitholder","Holds <b>5% or more</b> of a scheme's corpus (incl. entities it controls)"),
          ("Associate","Per Reg 2(d) of SEBI MF Regulations 2026"),
          ("Fundamental investment policies","Objectives, policies, terms that are fundamental attributes"),
          ("Trustee","Member of Board of Trustees or director of Trustee Company")]))
    sub("Appendix 3 — AMFI Code of Conduct for MFDs: scope & fiduciary duty", 5,
      L("Core values of a fiduciary: transparency, competency, fairness, integrity",
        "Applies to all ARN holders and binds directors, partners, sub-distributors, employees, representatives, sales personnel",
        "Investor's interest paramount; due diligence; independent professional judgment",
        "Avoid conflicts; disclose when unavoidable; disclose conflict when selling group/affiliate/associate schemes",
        "Financial incentive must not be the basis of recommendations; no aggressive sales tactics for targets",
        "No rebating / pass-back of commission; no gifts or gift-vouchers as inducement",
        "No collusion: over-transacting &amp; churning, splitting applications, payment defaults/diversion of funds, false claims for payouts, mis-selling (false statements, concealing facts/risks)"))
    sub("Appendix 3 — compliance, infrastructure, records", 4,
      L("Follow SEBI MF Regulations 2026 and SEBI/AMFI circulars on selling, distribution, advertising, performance disclosure; segregation of distribution and advisory (IA Regulations 2013)",
        "KYD compliance; diligent attestation and IPV for KYC",
        "Know SID, SAI, KIM; explain key features, fundamental attributes, risks",
        "Suitability: seek client's financial status, investment experience, objectives",
        "Representatives educated and experienced",
        "Confidentiality: no sharing/publishing without written consent, no third-party disclosure except by law, <b>no sharing with group companies for cross-marketing</b>; AMFI Data Sharing Principles; data protection laws; purge data when no longer needed",
        "Principal MFD must not engage sub-distributors without valid ARN",
        "Physical and digital infrastructure incl. cyber security; internal controls to detect/prevent mis-selling and fraud; insurance encouraged",
        "Records (physical/digital) incl. KYC and suitability correspondence, consent/dissent"))
    sub("Appendix 3 — client obligations", 5,
      L("Give full, updated scheme info (SAI, SID, addenda, performance, factsheets, portfolios, brochures); don't withhold material facts incl. unsuitability",
        "Highlight risk factors; no misrepresentation; urge reading SAI/SID/KIM",
        "Disclose all commissions from competing schemes considered",
        "Disclose list of MFs affiliated with; tell clients other products exist",
        "If MFD is associate/group/sponsor of an AMC: disclose association and total commission",
        "<b>MFDs cannot deal in Direct Plans</b> (SEBI letter 6 Sep 2021); digital platforms must state the scheme is Regular Plan with commission, hyperlink commission rates and offer documents",
        "No indicative portfolio, indicative yield or indicative return; never assure returns",
        "Where assured-return products are also sold, don't mis-sell MFs as assured/regular income; principal at risk",
        "Forms: investor's own accurate details; never fill MFD's or third-party contacts; changes only on investor's instruction; no tampering; write EUIN",
        "Help resolve grievances; use only AMC marketing material (no own material or AMC logo without written approval)",
        "Draw attention to risks: market risk &amp; loss of capital, force majeure, issuer default, segregation; suspension of redemption; NFO risks (price volatility, liquidity, delisting); winding up",
        "Compare only similar schemes with complete facts"))
    sub("Appendix 3 — other obligations & integrity", 4,
      L("NISM certification + AMFI ARN/EUIN, renewed on time; non-individuals ensure staff certified; quote valid ARN &amp; EUIN for regular-plan transactions",
        "Training: fiduciary duty, fraud prevention, responsible social media use",
        "Cooperate with AMCs, AMFI, SEBI, due-diligence agencies",
        "Promptly inform AMC &amp; AMFI of changes in status, constitution, address, contacts",
        "Refund clawback incentives (set-off or payment)",
        "Notify AMC &amp; AMFI if a representative commits moral turpitude, financial irregularity, is arrested or terminated for such acts",
        "Reg 3(3) IA Regulations 2013: no 'Adviser', 'Financial Adviser', 'Wealth Manager', 'Consultant' etc. in name unless SEBI-registered IA",
        "Tagline <b>'AMFI-registered Mutual Fund Distributor'</b> with/below name, font size ≥ <b>12</b> in printed communication; name + tagline on website, app, business cards, sign boards",
        "No fraudulent/unfair practices; no false or defamatory statements about AMCs, AMFI, schemes or other MFDs on any forum; no rumours"))
    sub("Appendix 4 — additional knowledge resources", 1,
      K("SID format (SEBI Nov 2023 simplification; Master Circular Mar 2026)","SAI &amp; KIM formats (Master Circular Jun 2024)","KYC info: amfiindia.com/kyc","Industry data (AMFI)","Global data: ici.org","Draft NFOs, SIDs, KIMs, SAIs on SEBI site","Investor education &amp; performance data on AMFI site"))
